cd /workspace && node -e "
const ExcelJS = require('exceljs');

async function main() {
  const text = \`Invoice #1042
Date: 2026-08-01
Total: \\\$2500.00\`;

  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Invoice Text');

  // Header
  sheet.getCell('A1').value = 'Line';
  sheet.getCell('B1').value = 'Text';
  sheet.getRow(1).font = { bold: true };

  // One line per row
  const lines = text.split('\n');
  lines.forEach((line, i) => {
    sheet.getCell(\`A\${i + 2}\`).value = i + 1;
    sheet.getCell(\`B\${i + 2}\`).value = line;
  });

  // Auto-fit column B width
  sheet.getColumn('B').width = 25;

  await workbook.xlsx.writeFile('invoice_data.xlsx');
  console.log('Saved invoice_data.xlsx');
}
main();
"
